function zdbx()
{
   if(_root.p2loaded == true)
   {
      if(_root.game.p1.mc.beida == 0)
      {
         _root.game.p1.mc.hp = _root.maxhp;
         _root.game.p1.mc.ql = 300;
      }
      if(_root.game.p2.mc.beida == 0)
      {
         _root.game.p2.mc.hp = _root.maxhp;
         _root.game.p2.mc.ql = 300;
      }
   }
}
